function openJournalDrawer(id){$('variationModal').hidden=false;$('variationTitle').textContent='Asiento de diario de origen';$('variationBalances').hidden=true;const wrap=$('variationRows').closest('.table-wrap');wrap.hidden=true;let frame=$('journalDrawerFrame');if(!frame){frame=document.createElement('iframe');frame.id='journalDrawerFrame';frame.className='journal-drawer-frame';$('variationTitle').insertAdjacentElement('afterend',frame)}frame.hidden=false;frame.src=`/journal-view.html?id=${encodeURIComponent(id)}`}
