function renderGeneralJournal(){const rows=data.rows||[],canReverse=Boolean(options.journalOptions?.canReverse);$('thead').innerHTML='<tr><th>Cuenta</th><th>Nombre de cuenta</th><th>Tercero / Entidad</th><th>Centro de costo</th><th>Detalle / Glosa</th><th class="number">Débito</th><th class="number">Crédito</th></tr>';const html=[];for(const journal of rows){const difference=Number(journal.difference||0),balanced=Math.abs(difference)<.005,origin=[journal.transaction_code,journal.module_category].filter(Boolean).join(' - ');html.push(`<tr class="journal-header ${balanced?'':'journal-unbalanced'}"><td colspan="7"><div class="journal-card-title"><div><button class="ledger-link" data-journal="${journal.journal_id}"><b>${escapeHtml(journal.journal_number)}</b></button><span class="journal-badge ${balanced?'balanced':'unbalanced'}">${balanced?'CUADRADO':`DESCUADRE: ${financial(difference)}`}</span><span class="journal-status">${escapeHtml(journal.status)}</span></div><div class="journal-actions"><button data-print-journal="${journal.journal_id}">Imprimir comprobante</button>${canReverse&&journal.status==='CONTABILIZADO'?(String(journal.journal_number).startsWith('ASI_PEN-')?`<button class="danger" data-reverse-pending="${journal.journal_id}">Reversar Pendiente</button>`:`<button class="danger" data-reverse-journal="${journal.journal_id}">Reversar asiento</button>`):''}</div></div><div class="journal-metadata"><span><small>Fecha</small>${escapeHtml(journal.date)}</span><span><small>Tipo y módulo</small><button class="ledger-link" data-origin-journal="${journal.journal_id}">${escapeHtml(origin||'Diario General')}</button></span><span><small>Documento de origen</small>${escapeHtml(journal.document_number||'—')}</span><span><small>Usuario</small>${escapeHtml(journal.created_by||'Sistema')}</span><span class="journal-memo"><small>Concepto general</small>${escapeHtml(journal.memo||'—')}</span></div></td></tr>`);for(const line of journal.lines||[])html.push(`<tr><td>${escapeHtml(line.account_number)}</td><td>${escapeHtml(line.account_name)}</td><td>${escapeHtml([line.entity_type,line.entity_name].filter(Boolean).join(': ')||'—')}</td><td>${escapeHtml(line.cost_center||'—')}</td><td>${escapeHtml(line.note||'—')}</td><td class="number">${financial(line.debit)}</td><td class="number">${financial(line.credit)}</td></tr>`);html.push(`<tr class="journal-footer"><td colspan="5">Subtotal del comprobante <span class="journal-badge ${balanced?'balanced':'unbalanced'}">${balanced?'CUADRADO':'DESCUADRADO'}</span></td><td class="number">${financial(journal.debit)}</td><td class="number">${financial(journal.credit)}</td></tr>`)}$('tbody').innerHTML=html.join('')||'<tr><td colspan="7">No hay comprobantes para los filtros seleccionados.</td></tr>';document.querySelectorAll('[data-journal],[data-origin-journal]').forEach(b=>b.onclick=()=>openJournalDrawer(b.dataset.journal||b.dataset.originJournal));document.querySelectorAll('[data-print-journal]').forEach(b=>b.onclick=()=>window.open(`/journal-view.html?id=${b.dataset.printJournal}&print=1`,'_blank','noopener'));document.querySelectorAll('[data-reverse-journal]').forEach(b=>b.onclick=()=>reverseJournal(b));document.querySelectorAll('[data-reverse-pending]').forEach(b=>b.onclick=()=>openPendingReversal(Number(b.dataset.reversePending)));const debit=Number(data.summary?.debit||0),credit=Number(data.summary?.credit||0),difference=debit-credit,balanced=Math.abs(difference)<.005;$('summary').innerHTML=`<div class="metric"><small>Total débitos del período</small><b>${financial(debit)}</b></div><div class="metric"><small>Total créditos del período</small><b>${financial(credit)}</b></div><div class="metric ${balanced?'reconciled':'unreconciled'}"><small>Partida doble del Diario General</small><b>${balanced?'CUADRADO':`DESCUADRE: ${financial(difference)}`}</b></div>`;renderPager()}
async function reverseJournal(button){if(!confirm('Se generará un nuevo asiento con débitos y créditos invertidos. El comprobante original quedará marcado como ANULADO. ¿Desea continuar?'))return;button.disabled=true;try{const result=await api(`/api/reports/accounting/journal/${button.dataset.reverseJournal}/reverse`,{method:'POST',body:JSON.stringify({})});alert(`La reversión fue generada correctamente. Nuevo asiento interno #${result.journalId}.`);await run()}catch(e){alert(e.message)}finally{button.disabled=false}}
let pendingReversalJournalId=null;
let pendingSupportLinks=[];
function resetPendingSupports(){pendingSupportLinks=[];$('pendingSupportLinkName').value='';$('pendingSupportLinkUrl').value='';$('pendingSupportFiles').value='';$('pendingSupportList').replaceChildren()}
$('pendingSupportFiles').onchange=()=>{const input=$('pendingSupportFiles');$('pendingReversalError').textContent='';if([...input.files].some(file=>file.size>5242880)){input.value='';renderPendingSupports();$('pendingReversalError').textContent='Cada archivo de respaldo debe pesar como máximo 5 MB.';return}renderPendingSupports()};
$('addPendingSupportLink').onclick=()=>{try{const url=new URL($('pendingSupportLinkUrl').value.trim());if(!['http:','https:'].includes(url.protocol))throw Error();pendingSupportLinks.push({support_type:'Enlace',display_name:$('pendingSupportLinkName').value.trim()||url.hostname,support_url:url.href});$('pendingSupportLinkName').value='';$('pendingSupportLinkUrl').value='';$('pendingReversalError').textContent='';renderPendingSupports()}catch{$('pendingReversalError').textContent='Ingrese un enlace de respaldo válido que comience con http:// o https://'}};
function renderPendingSupports(){
 $('pendingSupportList').replaceChildren();
 const addRow=(name,onRemove,url)=>{const row=document.createElement('li'),label=document.createElement(url?'a':'span'),remove=document.createElement('button');label.textContent=name;if(url){label.href=url;label.target='_blank';label.rel='noopener noreferrer'}remove.type='button';remove.textContent='Quitar';remove.setAttribute('aria-label',`Quitar ${name}`);remove.onclick=onRemove;row.append(label,remove);$('pendingSupportList').append(row)};
 [...$('pendingSupportFiles').files].forEach((file,index)=>addRow(file.name,()=>{const transfer=new DataTransfer();[...$('pendingSupportFiles').files].forEach((item,itemIndex)=>{if(itemIndex!==index)transfer.items.add(item)});$('pendingSupportFiles').files=transfer.files;renderPendingSupports()}));
 pendingSupportLinks.forEach((link,index)=>addRow(link.display_name,()=>{pendingSupportLinks.splice(index,1);renderPendingSupports()},link.support_url));
}
async function readPendingSupports(files){return Promise.all(files.map(async file=>{if(file.size>5242880)throw Error('Cada archivo de respaldo debe pesar como máximo 5 MB.');const file_data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result));reader.onerror=()=>reject(Error(`No fue posible leer ${file.name}.`));reader.readAsDataURL(file)});return{support_type:'Archivo',display_name:file.name,file_name:file.name,mime_type:file.type||'application/octet-stream',file_size:file.size,file_data}}))}

function pendingInvoiceEmptyLabel(){const value=$('pendingReversalDate').value,date=value?new Date(`${value}T12:00:00`):null,period=date&&!Number.isNaN(date.valueOf())?date.toLocaleDateString('es-CR',{month:'long',year:'numeric'}):'el mes seleccionado';return `No hay facturas de este cliente en ${period}`}
async function loadPendingReversalInvoices(includeJournal=false){if(!pendingReversalJournalId||!$('pendingReversalDate').value)return null;const select=$('pendingInvoice'),selected=select.value;select.disabled=true;select.innerHTML='<option value="">Consultando facturas...</option>';try{const result=await api(`/api/reports/accounting/pending-invoices/${pendingReversalJournalId}/reversal-options?date=${encodeURIComponent($('pendingReversalDate').value)}`),invoices=result.invoices||[];select.innerHTML=invoices.length?'<option value="">Seleccione una factura</option>'+invoices.map(invoice=>`<option value="${invoice.id}">${escapeHtml(invoice.number)} · ${escapeHtml(invoice.customer)} · ${escapeHtml(invoice.date)} · ${financial(invoice.total)}</option>`).join(''):`<option value="">${escapeHtml(pendingInvoiceEmptyLabel())}</option>`;if(invoices.some(invoice=>String(invoice.id)===selected))select.value=selected;return includeJournal?result:null}catch(error){select.innerHTML='<option value="">No fue posible consultar las facturas</option>';$('pendingReversalError').textContent=error.message;return null}finally{select.disabled=$('pendingReversalType').value!=='FACTURACION'}}
async function openPendingReversal(journalId){pendingReversalJournalId=journalId;$('pendingReversalError').textContent='';$('pendingReversalDate').value=new Date().toLocaleDateString('en-CA',{timeZone:'America/Costa_Rica'});try{const result=await loadPendingReversalInvoices(true);if(!result)throw Error($('pendingReversalError').textContent||'No fue posible consultar el asiento pendiente.');const journal=result.journal||{};$('pendingReversalSummary').innerHTML=`<div class="metric"><small>No. asiento original</small><b>${escapeHtml(journal.number)}</b></div><div class="metric"><small>Monto inicial</small><b>${financial(journal.initialLocal)}</b></div><div class="metric"><small>Reversado previamente</small><b>${financial(journal.reversedLocal)}</b></div><div class="metric reconciled"><small>Saldo disponible</small><b>${financial(journal.balanceLocal)}</b></div>`;$('pendingReversalAmount').value=Number(journal.balanceLocal||0).toFixed(2);$('pendingReversalAmount').max=String(journal.balanceLocal||0);$('pendingReversalType').value='';$('pendingErrorDescription').value='';resetPendingSupports();togglePendingReversalFields();$('pendingReversalModal').showModal()}catch(error){pendingReversalJournalId=null;alert(error.message)}}
function togglePendingReversalFields(){const kind=$('pendingReversalType').value;$('pendingInvoiceLabel').hidden=kind!=='FACTURACION';$('pendingErrorLabel').hidden=kind!=='ERROR_CORRECCION';$('pendingSupportsPanel').hidden=kind!=='ERROR_CORRECCION';['pendingSupportFiles','pendingSupportLinkName','pendingSupportLinkUrl','addPendingSupportLink'].forEach(id=>$(id).disabled=kind!=='ERROR_CORRECCION');if(kind!=='ERROR_CORRECCION')resetPendingSupports();$('pendingInvoice').required=kind==='FACTURACION';$('pendingInvoice').disabled=kind!=='FACTURACION';$('pendingErrorDescription').required=kind==='ERROR_CORRECCION';if(kind==='FACTURACION')loadPendingReversalInvoices()}
function closePendingReversal(){resetPendingSupports();pendingReversalJournalId=null;$('pendingReversalModal').close()}
$('pendingReversalType').onchange=togglePendingReversalFields;$('pendingReversalDate').onchange=()=>{if($('pendingReversalType').value==='FACTURACION')loadPendingReversalInvoices()};$('closePendingReversal').onclick=$('cancelPendingReversal').onclick=closePendingReversal;
function showPendingReversalSuccess(result){$('pendingSuccessNumber').textContent=result.number;$('pendingSuccessAmount').textContent=financial(result.amount);$('pendingSuccessRemaining').textContent=financial(result.remaining);$('pendingSuccessMessage').textContent=Number(result.remaining)>.005?'La reversión parcial fue contabilizada. El asiento original conserva el saldo indicado.':'El asiento pendiente quedó reversado en su totalidad.';$('viewPendingSuccessJournal').href=`/journal-view.html?id=${encodeURIComponent(result.journalId)}`;$('pendingReversalSuccess').showModal()}
