function updateBankMatchHint(){const erp=document.querySelector('input[name="erpMatch"]:checked'),bank=document.querySelector('input[name="bankMatch"]:checked'),hint=document.querySelector('.bank-match-hint');document.querySelectorAll('.bank-match-row').forEach(row=>row.classList.remove('selected-match','suggested-match'));erp?.closest('tr')?.classList.add('selected-match');bank?.closest('tr')?.classList.add('selected-match');if(!hint)return;if(!erp||!bank){hint.textContent='Seleccione un movimiento del ERP y uno del extracto para comparar sus montos y notas.';return}const difference=Number(erp.dataset.amount)-Number(bank.dataset.amount),matches=Math.abs(difference)<.005;hint.className=`bank-match-hint ${matches?'match-ok':'match-warning'}`;hint.innerHTML=matches?'<b>Los montos coinciden.</b> Revise las fechas, referencias y notas antes de conciliar.':`<b>Atención:</b> existe una diferencia de ${bankMoney(difference)} entre los movimientos seleccionados.`}
function parseDelimitedRow(line,separator){const cells=[];let value='',quoted=false;for(let i=0;i<line.length;i++){const char=line[i];if(char==='"'&&quoted&&line[i+1]==='"'){value+='"';i++}else if(char==='"')quoted=!quoted;else if(char===separator&&!quoted){cells.push(value.trim());value=''}else value+=char}cells.push(value.trim());return cells}
