function renderSummary(){$('summary').innerHTML=Object.entries(data.summary||{}).map(([k,v])=>`<div class="metric"><small>${labels[k]||k}</small><b>${typeof v==='boolean'?(v?'Cuadrado':'Descuadrado'):fmt(v)}</b></div>`).join('')}
function renderPager(){const pages=Math.max(1,Math.ceil(data.total/Number($('pageSize').value)));$('count').textContent=`${data.total||0} registros`;$('page').textContent=`Página ${page} de ${pages}`;$('prev').disabled=page<=1;$('next').disabled=page>=pages}
const escapeHtml=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function exportContext(){const subsidiary=(options.subsidiaries||[]).find(x=>String(x.id)===$('subsidiaries').value),currency=(options.currencies||[]).find(x=>String(x.id)===$('currency').value),period=(options.periods||[]).find(x=>String(x.id)===$('period').value),subsidiaryName=subsidiary?.name||'Subsidiaria',currencyLabel=currency?`${currency.code}${currency.name?` - ${currency.name}`:''}`:'moneda local',dateLabel=value=>value?new Date(`${value}T00:00:00`).toLocaleDateString('es-CR',{day:'2-digit',month:'long',year:'numeric'}):'',periodLabel=period?`${period.name} · ${dateLabel($('from').value)} al ${dateLabel($('to').value)}`:`Periodo comprendido del ${dateLabel($('from').value)} al ${dateLabel($('to').value)}`;$('printSubsidiary').textContent=subsidiaryName;$('printReportTitle').textContent=current?.[2]||'';$('printPeriod').textContent=periodLabel;$('printCurrency').textContent=`Expresado en ${currencyLabel}`;$('printLogo').src=subsidiary?.logoUrl||'';$('printLogo').hidden=!subsidiary?.logoUrl;return{subsidiaryName,currencyLabel,periodLabel,logoUrl:subsidiary?.logoUrl||''}}
function exportIncomeMatrix(type){const context=exportContext(),headers=[...$('thead').querySelectorAll('th')].map(cell=>cell.textContent.trim()),rows=[...$('tbody').querySelectorAll('tr')].map(row=>[...row.querySelectorAll('td')].map(cell=>cell.textContent.trim())),name=`${current[1]}-${$('columnView').value.toLowerCase()}-${$('to').value}`;if(type==='csv'){const csv=[headers,...rows].map(row=>row.map(value=>`"${String(value).replaceAll('"','""')}"`).join(',')).join('\r\n');download(new Blob(['\ufeff'+csv],{type:'text/csv'}),`${name}.csv`);return}const logo=context.logoUrl?`<img src="${escapeHtml(context.logoUrl)}" style="float:right;max-width:150px;max-height:82px">`:'';const table=`${logo}<h1>${escapeHtml(context.subsidiaryName)}</h1><h2>${escapeHtml(current[2])}</h2><p>${escapeHtml(context.periodLabel)}</p><p>Expresado en ${escapeHtml(context.currencyLabel)}</p><table><tr>${headers.map(value=>`<th>${escapeHtml(value)}</th>`).join('')}</tr>${rows.map(row=>`<tr>${row.map((value,index)=>`<td${index>1?' style="mso-number-format:#,##0.00"':''}>${escapeHtml(value)}</td>`).join('')}</tr>`).join('')}</table>`;download(new Blob([`<html><meta charset="utf-8">${table}</html>`],{type:'application/vnd.ms-excel'}),`${name}.xlsx`)}
function exportRows(type){if(!data.rows?.length)return alert('Genere un reporte con información antes de exportar.');if(current?.[1]==='income-statement'&&$('columnView').value!=='TOTAL'){exportIncomeMatrix(type);return}const context=exportContext(),keys=Object.keys(data.rows[0]).filter(k=>k!=='id'),name=`${current[1]}-${$('to').value}`;if(type==='csv'){const csv=[keys.map(k=>labels[k]||k),...data.rows.map(r=>keys.map(k=>String(r[k]??'').replaceAll('"','""')))].map(r=>r.map(v=>`"${v}"`).join(',')).join('\r\n');download(new Blob(['\ufeff'+csv],{type:'text/csv'}),`${name}.csv`)}else{const logo=context.logoUrl?`<img src="${escapeHtml(context.logoUrl)}" style="float:right;max-width:150px;max-height:82px">`:'';const table=`${logo}<h1>${escapeHtml(context.subsidiaryName)}</h1><h2>${escapeHtml(current[2])}</h2><p>${escapeHtml(context.periodLabel)}</p><p>Expresado en ${escapeHtml(context.currencyLabel)}</p><table><tr>${keys.map(k=>`<th>${labels[k]||k}</th>`).join('')}</tr>${data.rows.map(r=>`<tr>${keys.map(k=>`<td${moneyKeys.has(k)?' style="mso-number-format:#,##0.00"':''}>${r[k]??''}</td>`).join('')}</tr>`).join('')}<tr>${keys.map((k,i)=>moneyKeys.has(k)?`<td>=SUM(${String.fromCharCode(65+i)}2:${String.fromCharCode(65+i)}${data.rows.length+1})</td>`:'<td></td>').join('')}</tr></table>`;download(new Blob([`<html><meta charset="utf-8">${table}</html>`],{type:'application/vnd.ms-excel'}),`${name}.xlsx`)}}
const download=(blob,name)=>{const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};$('csv').onclick=()=>exportRows('csv');$('excel').onclick=()=>exportRows('excel');$('pdf').onclick=async()=>{if(current?.[1]==='pending-invoice-control')return generatePendingInvoicePdf();if(current?.[1]==='bank-balances')return generateBankBalancesPdf();exportContext();const logo=$('printLogo');if(!logo.hidden&&logo.src){try{await logo.decode()}catch{await new Promise(resolve=>{logo.onload=resolve;logo.onerror=resolve;setTimeout(resolve,1500)})}}const wide=current?.[1]==='income-statement'&&$('columnView').value!=='TOTAL'&&$('thead').querySelectorAll('th').length>6,style=wide?document.head.appendChild(document.createElement('style')):null;if(style)style.textContent='@page{size:A4 landscape;margin:10mm}';window.addEventListener('afterprint',()=>style?.remove(),{once:true});window.print()};
await init();const query=new URLSearchParams(location.search),requested=query.get('reporte');if(query.get('subsidiaryId')){$('subsidiaries').value=query.get('subsidiaryId');cascade()}if(query.get('bookId'))$('book').value=query.get('bookId');if(query.get('dateFrom'))$('from').value=query.get('dateFrom');if(query.get('dateTo'))$('to').value=query.get('dateTo');drilledAccountId=query.get('accountId')||null;if(reports.some(x=>x[1]===requested))openReport(requested);
document.addEventListener('click',event=>{const button=event.target.closest('[data-statement]');if(!button||!['receivables-aging','payables-aging'].includes(current?.[1]))return;event.preventDefault();event.stopImmediatePropagation();const entityId=button.dataset.statement,row=(data.rows||[]).find(item=>String(item.entity_id)===String(entityId)),subsidiary=(options.subsidiaries||[]).find(item=>String(item.id)===$('subsidiaries').value),currency=(options.currencies||[]).find(item=>String(item.id)===String(subsidiary?.currencyId));sessionStorage.setItem('nexo_account_statement',JSON.stringify({kind:current[1]==='receivables-aging'?'AR':'AP',report:current[1],entityId,entityCode:row?.entity_code,entityName:row?.entity_name,subsidiary,currency,cutoff:$('to').value,currencyMode:$('agingCurrencyMode')?.value||'LOCAL',filters:{...filters(),agingEntityId:entityId,page:1,pageSize:250}}));window.location.assign('/account-statement.html')},true);
function alignAgingInvoiceDetails(){const report=current?.[1],isPayable=report==='payables-aging',isReceivable=report==='receivables-aging';if((!isPayable&&!isReceivable)||$('agingView')?.value!=='SUMMARY')return;const buckets=['CURRENT','1_30','31_60','61_90','91_120','OVER_120'];document.querySelectorAll('tr.aging-child:not(.aging-aligned)').forEach(child=>{const documentId=child.querySelector('[data-aging-app]')?.dataset.agingApp,row=(data.rows||[]).find(item=>String(item.document_id)===String(documentId));if(!row)return;const viewUrl=isPayable?`/supplier-invoice-view.html?id=${encodeURIComponent(row.document_id)}`:`/sales-invoice-view.html?id=${encodeURIComponent(row.document_id)}`;child.classList.add('aging-aligned');child.innerHTML=`<td class="aging-document"><b>${escapeHtml(row.document_number)}</b><small>Emisión ${escapeHtml(row.issue_date)} · Vence ${escapeHtml(row.due_date)} · ${row.overdue_days} días</small></td>${buckets.map(bucket=>`<td class="number aging-${bucket.toLowerCase()}">${financial(row.bucket===bucket?row.pending:0)}</td>`).join('')}<td class="number">${financial(row.pending)}</td><td class="number">${financial(0)}</td><td class="number">${financial(row.pending)}</td><td><a class="ledger-link" href="${viewUrl}">Ver</a></td>`})}
new MutationObserver(()=>alignAgingInvoiceDetails()).observe($('tbody'),{childList:true});alignAgingInvoiceDetails();

async function generatePendingInvoicePdf(){
 const button=$('pdf'),label=button.textContent;button.disabled=true;button.textContent='Generando PDF...';$('message').textContent='';
 try{
  const selectedFilters=filters(),closed=pendingInvoiceTab==='CLOSED',company=(options.subsidiaries||[]).find(item=>String(item.id)===$('subsidiaries').value)||{},currency=(options.currencies||[]).find(item=>String(item.id)===String(company.currencyId))||{},customer=$('pendingCustomer').selectedOptions[0]?.textContent;
  const report=await api('/api/reports/accounting/pending-invoice-control',{method:'POST',body:JSON.stringify(selectedFilters)});
  const rows=(report.rows||[]).filter(row=>closed?row.status==='REVERSADO_TOTAL':['PENDIENTE','REVERSADO_PARCIAL'].includes(row.status));
  const html=pendingInvoicePdfHtml({rows,company,currency,from:selectedFilters.dateFrom,to:selectedFilters.dateTo,customer,closed});
  const result=await api('/api/reports/accounting/pending-invoice-control/pdf',{method:'POST',body:JSON.stringify({html,fileName:`control-pendientes-${closed?'reversados':'pendientes-parciales'}-${selectedFilters.dateTo}.pdf`})});
  const bytes=Uint8Array.from(atob(result.base64),char=>char.charCodeAt(0));download(new Blob([bytes],{type:'application/pdf'}),result.fileName);
 }catch(error){$('message').textContent=error.message}finally{button.disabled=false;button.textContent=label}
}

